import click
from pathlib import Path
from .analyzer import AnalysisEngine
from .patterns import ALL_PATTERNS
from .reporter import Reporter

@click.group()
@click.version_option()
def main():
    '''CodeSentry - AI-Powered Code Analysis & Education'''
    pass

@main.command()
@click.argument('file', type=click.Path(exists=True, path_type=Path))
@click.option('--teach', '-t', is_flag=True, help='Verbose explanations')
@click.option('--quick', '-q', is_flag=True, help='Minimal output')
@click.option('--format', '-f', type=click.Choice(['text', 'json']), default='text')
@click.option('--no-color', is_flag=True, help='Disable colors')
def scan(file, teach, quick, format, no_color):
    '''Scan a Python file for anti-patterns'''
    engine = AnalysisEngine(ALL_PATTERNS)
    result = engine.analyze_file(file)

    mode = 'teach' if teach else 'quick' if quick else 'default'
    reporter = Reporter(format=format, mode=mode, color=not no_color)
    reporter.report(result)

    # Exit code: 0=clean, 1=warnings, 2=errors, 3=critical
    raise SystemExit(result.max_severity_code)

@main.command()
def patterns():
    '''List all detectable patterns'''
    for p in ALL_PATTERNS:
        click.echo(f'{p.id}: {p.name} [{p.category}] - {p.severity}')

